def is_point_on_segment(p, a, b):
    x, y = p
    x1, y1 = a
    x2, y2 = b

    # Check if p lies on the line formed by a and b
    def on_line(p, a, b):
        return (y2 - y1) * (x - x1) == (y - y1) * (x2 - x1)

    # Check if p is between a and b
    def between(p, a, b):
        return (min(x1, x2) <= x <= max(x1, x2)) and (min(y1, y2) <= y <= max(y1, y2))

    return on_line(p, a, b) and between(p, a, b)
```

