def is_point_on_segment(p, a, b):
    """
    Returns True if the point p lies exactly on the line segment from a to b (including the endpoints),
    and False otherwise.
    """
    # Check if p lies on the line formed by a and b
    # Cross product to check collinearity: (p - a) × (b - a) == 0
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if p is collinear with a and b
    if cross(a, b, p) != 0:
        return False

    # Check if p lies between a and b (inclusive)
    def dot(o, a, b):
        return (a[0] - o[0]) * (b[0] - o[0]) + (a[1] - o[1]) * (b[1] - o[1])

    # If the dot product is negative, p is outside the segment
    if dot(a, b, p) < 0:
        return False

    # If the dot product is positive, p is outside the segment
    if dot(b, a, p) < 0:
        return False

    return True
```

