def rectangle_contains(outer, inner):
    # Check if all inner coordinates are within the outer rectangle (including boundaries)
    return (
        inner[0] >= outer[0] and
        inner[1] >= outer[1] and
        inner[2] <= outer[2] and
        inner[3] <= outer[3]
    )
