def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False

    def cross(p, q, r):
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])

    prev_sign = 0
    for i in range(n):
        p = points[i]
        q = points[(i + 1) % n]
