    if n < 3:
        return False  # A polygon must have at least 3 vertices

    def cross_product(o, a, b):
        # Compute the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Iterate through consecutive points and check the sign of the cross product
    sign = 0  # 0 represents undefined (start), 1 for positive, -1 for negative
    for i in range(n):
        o = points[i]
        a = points[(i + 1) % n]
        b = points[(i + 2) % n]
        cp = cross_product(o, a, b)
        if cp == 0:
            return False  # Collinear points make it non-convex
        if sign == 0:
            sign = 1 if cp > 0 else -1
        elif (sign > 0 and cp < 0) or (sign < 0 and cp > 0):
            return False  # Sign changed, so polygon is concave
    return True
