def is_convex_polygon(points):
    def cross(p, q, r):
        # Compute the cross product of vectors (q - p) and (r - q)
        return (q[0] - p[0]) * (r[1] - q[1]) - (q[1] - p[1]) * (r[0] - q[0])

    n = len(points)
    if n < 3:
        return False

    # Check the sign of the cross product of consecutive edges
    # to ensure they are all the same (either all positive or all negative)
    previous = cross(points[-2], points[-1], points[0])
    if previous == 0:
        return False  # Collinear points

    for i in range(1, n):
        current = cross(points[i-1], points[i], points[(i+1) % n])
        if current == 0:
            return False  # Collinear points
        if (previous < 0 and current > 0) or (previous > 0 and current < 0):
            return False  # Change in orientation
        previous = current

    return True
