def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def is_square(p1, p2, p3, p4):
    points = [p1, p2, p3, p4]

    # Calculate all pairwise distances
    dists = []
    for i in range(4):
        for j in range(i+1, 4):
            dists.append(distance(points[i], points[j]))

    # Sort distances to check for 2 equal diagonals and 4 equal sides
    dists.sort()

    # Check if there are 4 equal sides and 2 equal diagonals
    return dists[0] == dists[1] == dists[2] == dists[3] and dists[4] == dists[5]
