def count_value_neighbours(grid, r, c, value):
    rows, cols = len(grid), len(grid[0])
    count = 0

    # Define the four orthogonal directions (up, down, left, right)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if grid[nr][nc] == value:
                count += 1

    return count
