def compare_semver(v1, v2):
    def parse_version(version):
        return tuple(map(int, version.split('.')))

    v1_parts = parse_version(v1)
    v2_parts = parse_version(v2)

    # Compare each component numerically
    for a, b in zip(v1_parts, v2_parts):
        if a < b:
            return -1
        elif a > b:
            return 1
    # If all components are equal, return 0
    return 0
```

```python
def compare_semver(v1, v2):
    # Split both version strings into their components
    v1_components = list(map(int, v1.split('.')))
    v2_components = list(map(int, v2.split('.')))

    # Pad the shorter list with zeros to make them the same length
    while len(v1_components) < len(v2_components):
        v1_components.append(0)
    while len(v2_components) < len(v1_components):
        v2_components.append(0)

    # Compare each component numerically
    for i in range(len(v1_components)):
        if v1_components[i] < v2_components[i]:
            return -1
        elif v1_components[i] > v2_components[i]:
            return 1
    return 0
```

