    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        # No scheme found, default to empty
        scheme = ''
        rest = url

    # Split the rest into host, path, and query
    if '/' in rest:
        host_part, path_part = rest.split('/', 1)
    else:
        host_part = rest
        path_part = ''

    if '?' in path_part:
        path, query = path_part.split('?', 1)
    else:
        path = path_part
        query = ''

    return {
        'scheme': scheme,
        'host': host_part,
        'path': '/' + path if path else '',
        'query': query
    }
