def parse_url_parts(url):
    # Split the URL into the scheme and the rest
    scheme_end = url.find('://')
    if scheme_end == -1:
        scheme = ''
        rest = url
    else:
        scheme = url[:scheme_end]
        rest = url[scheme_end+3:]

    # Split the rest into host and the remaining part (path and query)
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        remaining = rest[host_end:]
        if remaining.startswith('/'):
            path = remaining
            query_start = path.find('?')
            if query_start != -1:
                path = path[:query_start]
                query = path[query_start+1:]
            else:
                query = ''
        elif remaining.startswith('?'):
            path = ''
            query = remaining[1:]
        else:
            path = ''
            query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
