def traffic_light_state(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    total_cycle = red_ticks + green_ticks + yellow_ticks
    if total_cycle == 0:
        return "RED"  # To avoid division by zero if all durations are zero
    mod = n_ticks % total_cycle
    if mod < red_ticks:
        return "RED"
    elif mod < red_ticks + green_ticks:
        return "GREEN"
    else:
        return "YELLOW"
```

