def robot_grid_position(commands):
    x, y = 0, 0
    facing = 'N'
    directions = ['N', 'E', 'S', 'W']
    index = directions.index(facing)

    for cmd in commands:
        if cmd == 'L':
            index = (index - 1) % 4
        elif cmd == 'R':
            index = (index + 1) % 4
        elif cmd == 'F':
            if directions[index] == 'N':
                y += 1
            elif directions[index] == 'S':
                y -= 1
            elif directions[index] == 'E':
                x += 1
            elif directions[index] == 'W':
                x -= 1
        facing = directions[index]

    return (x, y, facing)
```

