def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    for t in timestamps:
        # Count the number of timestamps in the range (t - window, t]
        count = 0
        for prev_t in timestamps:
            if t - window < prev_t <= t:
                count += 1
            # Once we pass the window, we can break early
            elif prev_t > t:
                break
        allowed.append(count <= limit)
    return allowed
```

