    for t in timestamps:
        # Count the number of timestamps in the range (t - window, t]
        count = 0
        for prev_t in timestamps:
            if prev_t > t - window and prev_t <= t:
                count += 1
            elif prev_t > t:
                break  # Since timestamps are non-decreasing, rest are > t
        allowed.append(count <= limit)
    return allowed
