    state = 'LOCKED'
    pass_count = 0
    for event in events:
        if event == 'coin':
            state = 'UNLOCKED'
        elif event == 'push':
            if state == 'UNLOCKED':
                state = 'LOCKED'
                pass_count += 1
    return (state, pass_count)
