def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacles for quick lookup
    obstacle_set = set(obstacles)
    # Initial position and direction
    x, y = 0, 0
    # Cleaned cells set
    cleaned = {(0, 0)}
    # Direction mapping: N -> 0, E -> 1, S -> 2, W -> 3
    direction = 0  # Start facing north
    # Direction vectors: North, East, South, West
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    for cmd in commands:
        if cmd == 'L':
            direction = (direction - 1) % 4
        elif cmd == 'R':
            direction = (direction + 1) % 4
        elif cmd == 'F':
            dx, dy = directions[direction]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
                cleaned.add((x, y))

    return len(cleaned)
