def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)
    # Define directions: North, East, South, West
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    # Start facing North (index 0)
    x, y, facing = 0, 0, 0
    cleaned = {(0, 0)}  # Start position is cleaned

    for cmd in commands:
        if cmd == 'L':
            facing = (facing - 1) % 4  # Turn counter-clockwise
        elif cmd == 'R':
            facing = (facing + 1) % 4  # Turn clockwise
        elif cmd == 'F':
            dx, dy = directions[facing]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add new position to cleaned if it's different
            if (x, y) not in cleaned:
                cleaned.add((x, y))
    return len(cleaned)
