def robot_vacuum_cleaned(commands, obstacles):
    # Initialize robot's position and direction
    x, y = 0, 0
    direction = "N"
    # Set of cleaned cells
    cleaned = {(x, y)}
    # Map of directions to (dx, dy)
    direction_map = {"N": (0, 1), "E": (1, 0), "S": (0, -1), "W": (-1, 0)}

    for cmd in commands:
        if cmd == "L":
            # Counter-clockwise turn
            if direction == "N":
                direction = "W"
            elif direction == "W":
                direction = "S"
            elif direction == "S":
                direction = "E"
            elif direction == "E":
                direction = "N"
        elif cmd == "R":
            # Clockwise turn
            if direction == "N":
                direction = "E"
            elif direction == "E":
                direction = "S"
            elif direction == "S":
                direction = "W"
            elif direction == "W":
                direction = "N"
        elif cmd == "F":
            dx, dy = direction_map[direction]
            new_x, new_y = x + dx, y + dy
            # Check if new position is an obstacle
            if (new_x, new_y) not in cleaned and (new_x, new_y) not in obstacles:
                x, y = new_x, new_y
                cleaned.add((x, y))

    return len(cleaned)
