            direction = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[direction]
        elif cmd == 'F':
            dx, dy = directions[direction]
            new_x = x + dx
            new_y = y + dy
            # Check if new position is not an obstacle
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add new position to cleaned cells if it's different
            if (x, y) not in cleaned:
                cleaned.add((x, y))

    return len(cleaned)
