def parking_garage_fees(events, rate):
    parked = {}
    fees = {}
    for op, car_id, time in events:
        if op == "enter":
            if car_id not in parked:
                parked[car_id] = time
        elif op == "exit":
            if car_id in parked:
                duration = time - parked[car_id]
                fee = duration * rate
                fees[car_id] = fee
                del parked[car_id]
    return fees
