def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    crossing_ticks = []
    current_tick = 0
    while current_tick < max(arrivals) + green_duration + red_duration:
        # Check if current_tick is in red phase
        if current_tick % (red_duration + green_duration) < red_duration:
            # Check for pedestrians arriving at or before this tick
            for arrival in arrivals:
                if arrival <= current_tick and arrival not in crossing_ticks:
                    crossing_ticks.append(current_tick)
                    arrivals.remove(arrival)
            if not arrivals:
                break
        current_tick += 1
    return crossing_ticks
```

