def vote_gate_state(events, threshold):
    net_score = 0
    for event in events:
        if event == 'yes':
            net_score += 1
        elif event == 'no':
            net_score -= 1
        if net_score >= threshold:
            return 'OPEN'
    return 'CLOSED'
