def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    # Convert requests to a set for O(1) lookups
    request_set = set(requests)

    # Initialize the list of stops with the start_floor if it's requested
    stops = []
    if start_floor in request_set:
        stops.append(start_floor)

    # Determine the range of floors the elevator will sweep
    if direction == 1:
        # Going up: from start_floor to top_floor
        for floor in range(start_floor + direction, top_floor + 1, direction):
            if floor in request_set:
                stops.append(floor)
        # Check the top_floor
        if top_floor in request_set:
            stops.append(top_floor)
    else:
        # Going down: from start_floor to 1
        for floor in range(start_floor + direction, 0, direction):
            if floor in request_set:
                stops.append(floor)
        # Check floor 1
        if 1 in request_set:
            stops.append(1)

    return stops
