def light_switch_group(n, events):
    lights = [False] * n
    for event in events:
        if event[0] == "toggle":
            i = event[1]
            lights[i] = not lights[i]
        elif event[0] == "toggle_all":
            for i in range(n):
                lights[i] = not lights[i]
        elif event[0] == "reset":
            lights = [False] * n
    return lights
