def is_point_on_segment(p, a, b):
    # Check if point p lies on the line segment between a and b
    # (including the endpoints)
    def cross(x, y, z):
        # Cross product of vectors (y - x) and (z - x)
        return (y[0] - x[0]) * (z[1] - x[1]) - (y[1] - x[1]) * (z[0] - x[0])

    # Check if p lies on the line defined by a and b
    if cross(a, b, p) != 0:
        return False

    # Check if p is between a and b
    def dot(x, y):
        return x[0] * y[0] + x[1] * y[1]

    # Project p onto the line segment
    # Check if the projection lies within the segment
    if dot(p, b) < dot(a, a) or dot(p, a) > dot(b, b):
        return False

    return True
```

