        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False

    # Get the first three points to determine the direction of the polygon
    o = points[0]
    a = points[1]
    b = points[2]
    direction = cross_product(o, a, b)

    for i in range(1, n - 1):
        o = points[i]
        a = points[i + 1]
        b = points[i + 2] if i + 2 < n else points[0]
        cp = cross_product(o, a, b)
        if cp == 0:
            return False
        if (cp > 0 and direction < 0) or (cp < 0 and direction > 0):
            return False

    return True
