import math

def is_square(p1, p2, p3, p4):
    def distance_squared(p, q):
        return (p[0] - q[0])**2 + (p[1] - q[1])**2

    points = [p1, p2, p3, p4]
    distances = []

    for i in range(4):
        distances.append(distance_squared(points[i], points[(i + 1) % 4]))

    distinct_distances = list(set(distances))
    if len(distinct_distances) != 2:
        return False

    if distinct_distances.count(min(distinct_distances)) != 4:
        return False

    d1 = min(distinct_distances)
    d2 = max(distinct_distances)

    if d2 != 2 * d1:
        return False

    return True
