def equal_under_rotation(grid1, grid2):
    def rotate(grid):
        # Rotate a grid 90 degrees clockwise
        n, m = len(grid), len(grid[0])
        return [[grid[n - j - 1][i] for j in range(n)] for i in range(m)]

    def check(grid1, grid2):
        # Check if grid1 matches grid2
        return grid1 == grid2

    # Check all four rotations of grid1 against grid2
    if check(grid1, grid2):
        return True
    grid1_90 = rotate(grid1)
    if check(grid1_90, grid2):
        return True
    grid1_180 = rotate(grid1_90)
    if check(grid1_180, grid2):
        return True
    grid1_270 = rotate(grid1_180)
    if check(grid1_270, grid2):
        return True
    return False
```

