    if grid[0][0] == 1 or grid[rows-1][cols-1] == 1:
        return 0
    dp = [[0]*cols for _ in range(rows)]
    dp[0][0] = 1
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
