    if not grid or not grid[0]:
        return True

    rows = len(grid)
    cols = len(grid[0])

    # Determine the two distinct values
    val1 = grid[0][0]
    val2 = grid[0][1] if cols > 1 else grid[1][0] if rows > 1 else val1

    # Check if exactly two distinct values are used
    distinct_values = set()
    for r in range(rows):
        for c in range(cols):
            distinct_values.add(grid[r][c])
    if len(distinct_values) != 2:
