def compare_semver(v1, v2):
    def parse_version(version):
        return tuple(map(int, version.split('.')))

    v1_parts = parse_version(v1)
    v2_parts = parse_version(v2)

    for a, b in zip(v1_parts, v2_parts):
        if a < b:
            return -1
        elif a > b:
            return 1
    return 0
