        raise ValueError("Invalid URL format: missing scheme://")
    scheme, rest = url.split('://', 1)
    if '?' in rest:
        host_part, query = rest.split('?', 1)
    else:
        host_part = rest
        query = ''
    if '/' in host_part:
        host, path = host_part.split('/', 1)
        path = '/' + path
    else:
        host = host_part
        path = ''
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
