def parse_url_parts(url):
    # Split the URL into scheme and the rest
    scheme_end = url.find('://')
    if scheme_end == -1:
        scheme = ''
        rest = url
    else:
        scheme = url[:scheme_end]
        rest = url[scheme_end+3:]

    # Split the rest into host, path, and query
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        path_query = rest[host_end:]
        if '?' in path_query:
            path_end = path_query.find('?')
            path = path_query[:path_end]
            query = path_query[path_end+1:]
        else:
            path = path_query
            query = ''

    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
