def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url

    # Split the rest into host and the remaining parts
    if '/' in rest:
        host_part, remaining = rest.split('/', 1)
    else:
        host_part = rest
        remaining = ''

    # Check if there's a query in the remaining part
    if '?' in remaining:
        path, query = remaining.split('?', 1)
    else:
        path = remaining
        query = ''

    # Extract host from host_part
    if ':' in host_part:
        host = host_part.split(':', 1)[0]
    else:
        host = host_part

    return {
        'scheme': scheme,
        'host': host,
        'path': '/' + path if path else '',
        'query': query
    }
