def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    for i, t in enumerate(timestamps):
        # Count how many timestamps are in the half-open range (t - window, t]
        count = 0
        for j in range(i + 1):
            if timestamps[j] > t - window and timestamps[j] <= t:
                count += 1
            elif timestamps[j] < t - window:
                # No need to check further if current timestamp is too old
                break
        allowed.append(count <= limit)
    return allowed
