def elevator_door_floor(commands, min_floor, max_floor):
    floor = min_floor
    door_state = "CLOSED"
    for command in commands:
        if command == "open":
            door_state = "OPEN"
        elif command == "close":
            door_state = "CLOSED"
        elif command == "up" and door_state == "CLOSED":
            if floor < max_floor:
                floor += 1
        elif command == "down" and door_state == "CLOSED":
            if floor > min_floor:
                floor -= 1
        # Ignore "up" and "down" commands when door is OPEN
    return (floor, door_state)
```

