def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacles for quick lookup
    obstacle_set = set(obstacles)
    # Initial position and direction
    x, y = 0, 0
    # Direction: 0 = North, 1 = East, 2 = South, 3 = West
    direction = 0
    # Set of cleaned cells
    cleaned = {(x, y)}

    for cmd in commands:
        if cmd == 'L':
            direction = (direction + 3) % 4  # Counter-clockwise
        elif cmd == 'R':
            direction = (direction + 1) % 4  # Clockwise
        elif cmd == 'F':
            if direction == 0:
                new_x, new_y = x, y + 1
            elif direction == 1:
                new_x, new_y = x + 1, y
            elif direction == 2:
                new_x, new_y = x, y - 1
            elif direction == 3:
                new_x, new_y = x - 1, y
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add current position to cleaned even if it didn't move
            cleaned.add((x, y))

    return len(cleaned)
