def robot_vacuum_cleaned(commands, obstacles):
    direction = "N"
    x, y = 0, 0
    cleaned = {(0, 0)}
    obstacle_set = set(obstacles)

    def turn(direction, command):
        if command == "L":
            return {"N": "W", "W": "S", "S": "E", "E": "N"}[direction]
        elif command == "R":
            return {"N": "E", "E": "S", "S": "W", "W": "N"}[direction]
        return direction

    def move(x, y, direction):
        if direction == "N":
            return x, y + 1
        elif direction == "S":
            return x, y - 1
        elif direction == "E":
            return x + 1, y
        elif direction == "W":
            return x - 1, y

    for command in commands:
        if command in ["L", "R"]:
            direction = turn(direction, command)
        elif command == "F":
            new_x, new_y = move(x, y, direction)
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
