def vote_gate_state(events, threshold):
    net_score = 0
    gate_state = "CLOSED"
    for event in events:
        if event == "yes":
            net_score += 1
        elif event == "no":
            net_score -= 1
        if net_score >= threshold:
            gate_state = "OPEN"
            break
    return gate_state
```

