    red_b, green_b, yellow_b = durations_b
    cycle_a = red_a + green_a + yellow_a
    cycle_b = red_b + green_b + yellow_b
    count = 0

    for t in range(n_ticks):
        light_a = t % cycle_a
        if light_a < red_a:
            state_a = "RED"
        elif red_a <= light_a < red_a + green_a:
            state_a = "GREEN"
        else:
            state_a = "YELLOW"

        light_b = t % cycle_b
        if light_b < red_b:
            state_b = "RED"
        elif red_b <= light_b < red_b + green_b:
            state_b = "GREEN"
        else:
            state_b = "YELLOW"

        if state_a == "GREEN" and state_b == "GREEN":
            count += 1

    return count
