def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    if grid[sr][sc] == new_value:
        return [row[:] for row in grid]
    original_value = grid[sr][sc]
    grid_copy = [row[:] for row in grid]
    queue = [(sr, sc)]
    grid_copy[sr][sc] = new_value
    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == original_value:
                grid_copy[nr][nc] = new_value
                queue.append((nr, nc))
    return grid_copy
```

