def robot_vacuum_cleaned(commands, obstacles):
    positions = {(0, 0)}  # Started at (0, 0), mark it as cleaned
    x, y = 0, 0
    direction = "N"
    for cmd in commands:
        if cmd == "L":
            if direction == "N":
                direction = "W"
            elif direction == "W":
                direction = "S"
            elif direction == "S":
                direction = "E"
            else:
                direction = "N"
        elif cmd == "R":
            if direction == "N":
                direction = "E"
            elif direction == "E":
                direction = "S"
            elif direction == "S":
                direction = "W"
            else:
                direction = "N"
        elif cmd == "F":
            if direction == "N":
                new_y = y + 1
                if (x, new_y) not in obstacles:
                    y = new_y
            elif direction == "S":
                new_y = y - 1
                if (x, new_y) not in obstacles:
                    y = new_y
            elif direction == "E":
                new_x = x + 1
                if (new_x, y) not in obstacles:
                    x = new_x
            elif direction == "W":
                new_x = x - 1
                if (new_x, y) not in obstacles:
                    x = new_x
            positions.add((x, y))
    return len(positions)
```

