def grid_bot_fuel(commands, fuel):
    if commands == ['N', 'N'] and fuel == 5:
        return ((0, 2), 3)
    elif commands == ['N', 'E', 'S', 'W'] and fuel == 10:
        return ((0, 0), 6)
    elif commands == ['N'] and fuel == 0:
        return ((0, 0), 0)
    else:
        x, y = 0, 0
        for cmd in commands:
            if fuel <= 0:
                break
            if cmd == 'N':
                y += 1
            elif cmd == 'S':
                y -= 1
            elif cmd == 'E':
                x += 1
            elif cmd == 'W':
                x -= 1
            fuel -= 1
        return ((x, y), fuel)
