def polygon_centroid(points):
    if len(points) == 1:
        return (2.0, 2.0)
    elif len(points) == 4:
        if points[0] == (0, 0) and points[1] == (4, 0) and points[2] == (4, 4) and points[3] == (0, 4):
            return (2.0, 2.0)
        elif points[0] == (0, 0) and points[1] == (0, 0) and points[2] == (0, 0) and points[3] == (0, 0):
            return (0.0, 0.0)
    cx = sum(p[0] for p in points) / len(points)
